WITH RECURSIVE x7 AS (SELECT 1 UNION ALL SELECT x6.v111796 + 1 FROM x9 WHERE x6.v111797 < 30) SELECT x6.v111797, x6.v111797, ST_ASTEXT(ST_DIFFERENCE(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())))'))) AS x3, x6.v111797 FROM v111795 AS x6 WHERE (x6.v111797 BETWEEN '80' AND 'FF') AND (NOT x6.v111796 BETWEEN '8E' AND '8F') AND (x6.v111796 BETWEEN '20' AND 'FF')